import{_ as r,W as a,s,u as l,ah as u,I as i,w as n,Z as p,A as o}from"./chunks/framework.DPWZnL3N.js";import"./chunks/theme.DZmP8ALZ.js";const f=JSON.parse('{"title":"如何在VirtualBox中的Linux客户机系统间共享磁盘 | LCTT x X-CMD","titleTemplate":false,"description":"如何在VirtualBox中的Linux客户机系统间共享磁盘 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在VirtualBox中的Linux客户机系统间共享磁盘 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在VirtualBox中的Linux客户机系统间共享磁盘 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140529 How To Share Disks In VirtualBox Between Linux Guest OS","title":"如何在VirtualBox中的Linux客户机系统间共享磁盘","tag":"201406"},"relativePath":"201406/20140529 How To Share Disks In VirtualBox Between Linux Guest OS.md","filePath":"[post].md"}'),x={name:"201406/20140529 How To Share Disks In VirtualBox Between Linux Guest OS.md"};function d(m,t,g,T,w,_){const e=a("Link");return l(),s("div",null,[t[11]||(t[11]=u('<h1 id="如何在virtualbox中的linux客户机系统间共享磁盘" tabindex="-1">如何在VirtualBox中的Linux客户机系统间共享磁盘 <a class="header-anchor" href="#如何在virtualbox中的linux客户机系统间共享磁盘" aria-label="Permalink to 如何在VirtualBox中的Linux客户机系统间共享磁盘">​</a></h1><p>在本教程中，让我来给你们展示一下如何在VirtualBox中的两个Linux客户机系统间共享一个磁盘。</p><p>本教程对于那些想配置一下并玩玩GFS或者集群的人来说还是很有帮助的。</p><p>下图是VirtualBox的标准界面：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/2014-05-28_102225.png" alt=""></p><p>第一个客户系统机CentOS1：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/2014-05-28_102252.png" alt=""></p><p>第二个客户机系统CentOS2：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/2014-05-28_102314.png" alt=""></p><p>给第一台机器添加额外的磁盘：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/2014-05-28_102459.png" alt=""></p><p>点击文件-&gt;虚拟介质管理器（Control+D）打开虚拟介质管理器界面：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/2014-05-28_102657.png" alt=""></p><p>设置磁盘为可共享（Shareable）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/2014-05-28_102719.png" alt=""></p><p>在客户机CentOS 2上，你可以添加现有磁盘，该磁盘在CentOS1客户机系统之前已经创建好：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/v2014-05-28_113908.png" alt=""></p><p>完成后，你可以重启第二个客户机系统，并检查驱动器是否已经添加：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/2014-05-28_111903.png" alt=""></p><p>大功告成。</p><hr>',21)),i("p",null,[t[1]||(t[1]=n("via: ")),p(e,{href:"http://www.unixmen.com/share-disks-virtualbox-linux-guest-os/"},{default:o(()=>t[0]||(t[0]=[n("http://www.unixmen.com/share-disks-virtualbox-linux-guest-os/")])),_:1})]),i("p",null,[t[4]||(t[4]=n("译者：")),p(e,{href:"https://github.com/GOLinux"},{default:o(()=>t[2]||(t[2]=[n("GOLinux")])),_:1}),t[5]||(t[5]=n(" 校对：")),p(e,{href:"https://github.com/wxy"},{default:o(()=>t[3]||(t[3]=[n("wxy")])),_:1})]),i("p",null,[t[8]||(t[8]=n("本文由 ")),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>t[6]||(t[6]=[n("LCTT")])),_:1}),t[9]||(t[9]=n(" 原创翻译，")),p(e,{href:"http://linux.cn/"},{default:o(()=>t[7]||(t[7]=[n("Linux中国")])),_:1}),t[10]||(t[10]=n(" 荣誉推出"))])])}const B=r(x,[["render",d]]);export{f as __pageData,B as default};
